          "id": "s1.qualifiers",
          "kind": "qualifiers",
          "title": "Qualifiers",
          "theme": "Reading an opponent",
          "rival": "host",
          "style": "calculator",
          "lessons": [],
          "intro": [
            "Welcome to the Tournament.",
            "Three quick matches decide who gets in. Every opponent here hides how they play.",
