          "kind": "arc",
          "title": "Arc 1",
          "theme": "Bluffing and signals",
          "rival": "vesper",
          "style": "manipulator",
          "lessons": [
            "signaling",
            "credibility",
            "brinkmanship"
          ],
          "intro": [
            "Vesper never raises her voice. She never needs to.",
